argv:
$ErrorActionPreference='Stop';
$targets=@(
  '6abda62d-8198-83ed-aaa2-40b16f96a8a0',
  '6abda64b-aac4-83eb-adee-dc7143ca5d2b',
  '6abf3eb2-40ec-83eb-9f7f-c4a32ad11fc0',
  '6abda61c-a440-83ed-9482-1d0fc7923e03',
  '6abe03fa-9728-83eb-90d2-5ee81bbac12c',
  '6ab8bed2-8d0c-83eb-b793-8e504335a57d'
);
function Get-ConvId([string]$url){
  try {
    $u=[uri]$url; $p=$u.AbsolutePath.Trim('/').Split('/');
    if($p.Length -eq 2 -and $p[0] -eq 'c'){ return $p[1] }
    if($p.Length -eq 4 -and $p[0] -eq 'g' -and $p[2] -eq 'c'){ return $p[3] }
  } catch {}
  return ''
}
$list=@(Invoke-RestMethod -Uri 'http://127.0.0.1:17410/json/list' -TimeoutSec 3);
$out=@();
foreach($cid in $targets){
  $m=@($list | Where-Object { $_.type -eq 'page' -and (Get-ConvId $_.url) -eq $cid });
  if($m.Count -gt 1){ throw "duplicate exact conversation tabs: $cid" }
  if($m.Count -eq 1){ $out += [pscustomobject]@{conversationId=$cid;state='already_open';id=$m[0].id;url=$m[0].url}; continue }
  $url='https://chatgpt.com/c/'+$cid;
  $created=Invoke-RestMethod -Method Put -Uri ('http://127.0.0.1:17410/json/new?'+[uri]::EscapeDataString($url)) -TimeoutSec 3;
  $out += [pscustomobject]@{conversationId=$cid;state='opened';id=$created.id;url=$created.url};
}
$out | ConvertTo-Json -Depth 3 -Compress
